// test_full_resolution.rs - Test qualified path resolution with full symbol map
// Generated by step4_bootstrap - Test Full Resolution

use split_decls_genesis::{resolve_qualified_dependency};
use serde_json;
use std::collections::HashMap;

fn main() {
    println!("🔍 Testing qualified path resolution with full symbol map...");
    
    // Load full symbol map
    let symbol_map_json: HashMap<String, serde_json::Value> = 
        serde_json::from_str(&std::fs::read_to_string("symbol_map.json").unwrap()).unwrap();
    
    // Convert to our Symbol format
    let mut symbol_map = HashMap::new();
    for (name, data) in symbol_map_json {
        if let (Some(symbol_type), Some(source_file), Some(crate_name)) = (
            data["symbol_type"].as_str(),
            data["source_file"].as_str(), 
            data["crate_name"].as_str()
        ) {
            let dependencies = data["dependencies"].as_array()
                .map(|arr| arr.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect())
                .unwrap_or_default();
                
            symbol_map.insert(name.clone(), split_decls_genesis::Symbol {
                name: name.clone(),
                symbol_type: symbol_type.to_string(),
                source_file: source_file.to_string(),
                crate_name: crate_name.to_string(),
                dependencies,
            });
        }
    }
    
    println!("✅ Loaded {} symbols", symbol_map.len());
    
    // Test qualified path resolution
    let test_paths = vec!["env::var", "env::vars", "env::var_os"];
    
    for path in test_paths {
        match resolve_qualified_dependency(path, &symbol_map) {
            Some(location) => {
                println!("  ✅ {}: {}", path, location);
            },
            None => {
                println!("  ❌ {}: not resolved", path);
                
                // Debug: check if we have the function
                let parts: Vec<&str> = path.split("::").collect();
                if parts.len() == 2 {
                    let function = parts[1];
                    if let Some(symbol) = symbol_map.get(function) {
                        println!("    🔍 Found '{}' function in {}", function, symbol.source_file);
                    }
                }
            }
        }
    }
}
